<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $organization->name }} energy operations report</title><style>body{font:15px/1.5 Arial,sans-serif;color:#102a33;margin:40px}header{border-bottom:3px solid #0b8f7a;margin-bottom:30px}h1,h2{margin:.2em 0}small{color:#60737a}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{border:1px solid #cbd9d4;border-radius:12px;padding:16px;margin:14px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #dbe5e1;padding:8px}@media print{.no-print{display:none}body{margin:18mm}.card{break-inside:avoid}}</style></head><body><button class="no-print" onclick="window.print()">Print report</button><header><small>CALDREN ENERGY OPERATIONS</small><h1>{{ $organization->name }}</h1><p>Portfolio report generated {{ now()->format('F j, Y H:i') }}. Forecasts and opportunities are estimates and decision support for human review.</p></header><section class="summary"><div class="card"><strong>{{ $buildings->count() }}</strong><br>Buildings</div><div class="card"><strong>{{ $alerts->count() }}</strong><br>Open or acknowledged alerts</div><div class="card"><strong>{{ $opportunities->count() }}</strong><br>Active opportunities</div></section><h2>Building performance</h2><table><thead><tr><th>Building</th><th>30-day energy</th><th>Highest site peak</th><th>Average coverage</th><th>Latest forecast</th></tr></thead><tbody>@foreach($buildings as $building)<tr><td>{{ $building->name }}</td><td>{{ number_format($building->dailySummaries->sum('kwh'),1) }} kWh</td><td>{{ number_format($building->dailySummaries->max('peak_kw')??0,1) }} kW</td><td>{{ number_format($building->dailySummaries->avg('coverage_percent')??0,1) }}%</td><td>{{ ucfirst($building->forecasts->first()?->status ?? 'Not available') }}</td></tr>@endforeach</tbody></table><h2>Operational alerts</h2>@forelse($alerts as $alert)<div class="card"><strong>{{ $alert->title }}</strong> · {{ ucfirst($alert->severity) }} · {{ $alert->building?->name ?? 'Workspace' }}<p>{{ $alert->message }}</p></div>@empty<p>No current alerts.</p>@endforelse<h2>Opportunity register</h2><table><thead><tr><th>Opportunity</th><th>Building</th><th>Priority</th><th>Status</th><th>Assignee</th></tr></thead><tbody>@foreach($opportunities as $opportunity)<tr><td>{{ $opportunity->title }}</td><td>{{ $opportunity->building?->name ?? 'Portfolio' }}</td><td>{{ ucfirst($opportunity->priority) }}</td><td>{{ ucfirst($opportunity->status) }}</td><td>{{ $opportunity->assignee?->name ?? 'Unassigned' }}</td></tr>@endforeach</tbody></table></body></html>
